// =========================================================
// Enhance Vocabulary - Request codes
// =========================================================

private static final int EV_REQUEST_OPEN_DOCUMENT = 7351;
private static final int EV_REQUEST_CREATE_DOCUMENT = 7352;
private static final int EV_REQUEST_NOTIFICATION_PERMISSION = 7354;

private static final String EV_NOTIFICATION_WORD_EXTRA =
    "com.epicgames.unreal.EV_NOTIFICATION_WORD";

private static final String EV_PENDING_NOTIFICATION_WORD =
    "PendingNotificationWord";

private String EVPendingNotificationWord = "";


// =========================================================
// Enhance Vocabulary - File exchange state
// =========================================================

private byte[] EVFileExchangePendingSaveBytes = null;

private String EVFileExchangePendingSaveFileName = "";

private String EVFileExchangePendingSaveMimeType = "";


// =========================================================
// Enhance Vocabulary - Notification configuration
// =========================================================

private static final String EV_VOCABULARY_CHANNEL_ID =
    "ev_vocabulary_reminders";

private static final int EV_VOCABULARY_NOTIFICATION_ID = 7353;

private static final String EV_NOTIFICATION_PREFERENCES =
    "EVNotificationPreferences";

private static final String EV_NOTIFICATION_PERMISSION_REQUESTED =
        "NotificationPermissionRequested";

private static final String EV_NOTIFICATION_ENABLED =
        "VocabularyAlarmEnabled";

private static final String EV_NOTIFICATION_INTERVAL_MILLISECONDS =
        "VocabularyAlarmIntervalMilliseconds";

private static final String EV_NOTIFICATION_MODE =
        "VocabularyAlarmMode";

// =========================================================
// Save file
// =========================================================

public void AndroidThunkJava_EV_SaveBytesToUserSelectedLocation(
    String suggestedFileName,
    String mimeType,
    byte[] bytes)
{
    EVFileExchangePendingSaveFileName =
        suggestedFileName;

    EVFileExchangePendingSaveMimeType =
        mimeType;

    EVFileExchangePendingSaveBytes =
        bytes;

    Intent intent =
        new Intent(Intent.ACTION_CREATE_DOCUMENT);

    intent.addCategory(
        Intent.CATEGORY_OPENABLE);

    intent.setType(
        mimeType);

    intent.putExtra(
        Intent.EXTRA_TITLE,
        suggestedFileName);

    startActivityForResult(
        intent,
        EV_REQUEST_CREATE_DOCUMENT);
}


public native void nativeEVFileSaveCompleted(
    boolean bSuccess,
    boolean bCancelled,
    String fileName,
    String errorMessage);


// =========================================================
// Import file
// =========================================================

public void AndroidThunkJava_EV_PickImportFile(String mimeType)
{
    Intent intent =
        new Intent(Intent.ACTION_OPEN_DOCUMENT);

    intent.addCategory(Intent.CATEGORY_OPENABLE);
    intent.setType("*/*");

    startActivityForResult(
        intent,
        EV_REQUEST_OPEN_DOCUMENT);
}


public native void nativeEVImportFilePicked(
    boolean bSuccess,
    boolean bCancelled,
    String fileName,
    byte[] bytes,
    String errorMessage);


// =========================================================
// Notification permission
// =========================================================

public boolean AndroidThunkJava_EV_AreNotificationsEnabled()
{
    if (Build.VERSION.SDK_INT >= 33)
    {
        if (checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)
            != PackageManager.PERMISSION_GRANTED)
        {
            return false;
        }
    }

    NotificationManager notificationManager =
        (NotificationManager)getSystemService(Context.NOTIFICATION_SERVICE);

    return notificationManager != null
        && notificationManager.areNotificationsEnabled();
}

public void AndroidThunkJava_EV_OpenNotificationSettings()
{
    Intent intent = new Intent();

    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O)
    {
        intent.setAction(Settings.ACTION_APP_NOTIFICATION_SETTINGS);
        intent.putExtra(Settings.EXTRA_APP_PACKAGE, getPackageName());
    }
    else
    {
        intent.setAction("android.settings.APP_NOTIFICATION_SETTINGS");
        intent.putExtra("app_package", getPackageName());
        intent.putExtra("app_uid", getApplicationInfo().uid);
    }

    startActivity(intent);
}

public void AndroidThunkJava_EV_RequestNotificationPermission()
{
    runOnUiThread(new Runnable()
    {
        @Override
        public void run()
        {
            /*
             * Android versions below 13 do not require the
             * POST_NOTIFICATIONS runtime permission. Resolve the
             * pending Unreal request immediately instead of leaving
             * the controller waiting for a callback that cannot occur.
             */
            if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU)
            {
                nativeEVNotificationPermissionResult(true);
                return;
            }

            if (checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)
                == PackageManager.PERMISSION_GRANTED)
            {
                nativeEVNotificationPermissionResult(true);
                return;
            }

            getSharedPreferences(
                    EV_NOTIFICATION_PREFERENCES,
                    Context.MODE_PRIVATE)
                .edit()
                .putBoolean(
                    EV_NOTIFICATION_PERMISSION_REQUESTED,
                    true)
                .apply();

            /*
             * Use GameActivity's Activity API directly, matching the
             * working file-exchange startActivityForResult flow.
             */
            requestPermissions(
                new String[]
                {
                    Manifest.permission.POST_NOTIFICATIONS
                },
                EV_REQUEST_NOTIFICATION_PERMISSION);
        }
    });
}

public boolean AndroidThunkJava_EV_HasRequestedNotificationPermission()
{
    /*
     * Android versions below 13 do not use the POST_NOTIFICATIONS
     * runtime permission dialog.
     */
    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU)
    {
        return true;
    }

    return getSharedPreferences(
            EV_NOTIFICATION_PREFERENCES,
            android.content.Context.MODE_PRIVATE)
        .getBoolean(
            EV_NOTIFICATION_PERMISSION_REQUESTED,
            false);
}

public native void nativeEVNotificationPermissionResult(
    boolean bGranted);

// =========================================================
// Vocabulary notification
// =========================================================

public void AndroidThunkJava_EV_TestAlarm()
{
    EVVocabularyAlarmReceiver.schedule(
        this,
        60,
        "Alarm fired!",
        0);
}

public boolean AndroidThunkJava_EV_ScheduleVocabularyNotifications(
    int intervalSeconds,
    String serializedWords,
    int notificationMode)
{
    return EVVocabularyAlarmReceiver.schedule(
        this,
        intervalSeconds,
        serializedWords,
        notificationMode);
}

public boolean AndroidThunkJava_EV_CancelVocabularyNotifications()
{
    return EVVocabularyAlarmReceiver.cancel(this);
}
public boolean AndroidThunkJava_EV_IsVocabularyNotificationScheduleEnabled()
{
    return getSharedPreferences(EV_NOTIFICATION_PREFERENCES, Context.MODE_PRIVATE)
        .getBoolean(EV_NOTIFICATION_ENABLED, false);
}

public int AndroidThunkJava_EV_GetVocabularyNotificationIntervalSeconds()
{
    long intervalMilliseconds =
        getSharedPreferences(EV_NOTIFICATION_PREFERENCES, Context.MODE_PRIVATE)
            .getLong(EV_NOTIFICATION_INTERVAL_MILLISECONDS, 0L);

    return intervalMilliseconds > 0L
        ? (int)(intervalMilliseconds / 1000L)
        : 0;
}

public int AndroidThunkJava_EV_GetVocabularyNotificationMode()
{
    return getSharedPreferences(EV_NOTIFICATION_PREFERENCES, Context.MODE_PRIVATE)
        .getInt(EV_NOTIFICATION_MODE, 0);
}

public String AndroidThunkJava_EV_ConsumePendingNotificationWord()
{
    String pendingWord = EVPendingNotificationWord;
    EVPendingNotificationWord = "";

    if (pendingWord == null || pendingWord.isEmpty())
    {
        android.content.SharedPreferences preferences =
            getSharedPreferences(EV_NOTIFICATION_PREFERENCES, Context.MODE_PRIVATE);

        pendingWord = preferences.getString(EV_PENDING_NOTIFICATION_WORD, "");

        if (pendingWord != null && !pendingWord.isEmpty())
        {
            preferences.edit().remove(EV_PENDING_NOTIFICATION_WORD).apply();
        }
    }

    Intent currentIntent = getIntent();
    if ((pendingWord == null || pendingWord.isEmpty()) && currentIntent != null)
    {
        pendingWord = currentIntent.getStringExtra(EV_NOTIFICATION_WORD_EXTRA);
        currentIntent.removeExtra(EV_NOTIFICATION_WORD_EXTRA);
    }

    return pendingWord != null ? pendingWord : "";
}


public void AndroidThunkJava_EV_ShowVocabularyNotification(
    final String word)
{
    if (word == null || word.isEmpty())
    {
        return;
    }

    runOnUiThread(new Runnable()
    {
        @Override
        public void run()
        {
            if (Build.VERSION.SDK_INT >= 33)
            {
                if (checkSelfPermission(
                        Manifest.permission.POST_NOTIFICATIONS)
                    != PackageManager.PERMISSION_GRANTED)
                {
                    return;
                }
            }

            NotificationManager notificationManager =
                (NotificationManager)getSystemService(
                    Context.NOTIFICATION_SERVICE);

            if (notificationManager == null)
            {
                return;
            }

            if (Build.VERSION.SDK_INT >=
                Build.VERSION_CODES.O)
            {
                NotificationChannel channel =
                    new NotificationChannel(
                        EV_VOCABULARY_CHANNEL_ID,
                        "Vocabulary reminders",
                        NotificationManager.IMPORTANCE_HIGH);

                channel.setDescription(
                    "Periodic vocabulary word reminders");

                notificationManager.createNotificationChannel(
                    channel);
            }

            Intent openWordIntent =
                new Intent(GameActivity.this, GameActivity.class)
                    .putExtra(EV_NOTIFICATION_WORD_EXTRA, word)
                    .addFlags(
                        Intent.FLAG_ACTIVITY_CLEAR_TOP |
                        Intent.FLAG_ACTIVITY_SINGLE_TOP);

            int pendingIntentFlags = PendingIntent.FLAG_UPDATE_CURRENT;

            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M)
            {
                pendingIntentFlags |= PendingIntent.FLAG_IMMUTABLE;
            }

            PendingIntent contentIntent = PendingIntent.getActivity(
                GameActivity.this,
                EV_VOCABULARY_NOTIFICATION_ID,
                openWordIntent,
                pendingIntentFlags);

            Notification.Builder builder;

            if (Build.VERSION.SDK_INT >=
                Build.VERSION_CODES.O)
            {
                builder =
                    new Notification.Builder(
                        GameActivity.this,
                        EV_VOCABULARY_CHANNEL_ID);
            }
            else
            {
                builder =
                    new Notification.Builder(
                        GameActivity.this);

                builder.setPriority(
                    Notification.PRIORITY_HIGH);
            }

            builder
                .setSmallIcon(
                    getApplicationInfo().icon)
                .setContentTitle(
                    "Enhance Vocabulary")
                .setContentText(
                    word)
                .setStyle(
                    new Notification.BigTextStyle()
                        .bigText(word))
                .setCategory(
                    Notification.CATEGORY_REMINDER)
                .setAutoCancel(true)
                .addAction(
                    0,
                    "CANCEL",
                    PendingIntent.getBroadcast(
                        GameActivity.this,
                        7356,
                        new Intent(
                            GameActivity.this,
                            EVVocabularyAlarmReceiver.class)
                            .setAction(
                                EVVocabularyAlarmReceiver.ACTION_CANCEL),
                        PendingIntent.FLAG_UPDATE_CURRENT |
                        PendingIntent.FLAG_IMMUTABLE));

            if (contentIntent != null)
            {
                builder.setContentIntent(
                    contentIntent);
            }

            notificationManager.notify(
                EV_VOCABULARY_NOTIFICATION_ID,
                builder.build());
        }
    });
}

