if (newIntent != null)
{
    String notificationWord =
        newIntent.getStringExtra(EV_NOTIFICATION_WORD_EXTRA);

    if (notificationWord != null && !notificationWord.isEmpty())
    {
        EVPendingNotificationWord = notificationWord;
        newIntent.removeExtra(EV_NOTIFICATION_WORD_EXTRA);
