// =========================================================
// Notification permission result
// =========================================================

if (requestCode == EV_REQUEST_NOTIFICATION_PERMISSION)
{
    final boolean bGranted =
        grantResults != null &&
        grantResults.length > 0 &&
        grantResults[0] == PackageManager.PERMISSION_GRANTED;

    nativeEVNotificationPermissionResult(
        bGranted);

    return;
}
